import Link from "next/link";
type Params = Promise<{ slug?: string[] }>;
export default async function Pokemon({ params }: { params: Params }) {
  //const resolvedParams=await params
  const { slug = [] } = await params;
  //resolvedParams.slug || []

  //if no sluge
  if (slug?.length === 0) {
    const type = [
      "fire",
      "water",
      "rock",
      "electric",
      "dragon",
      "posion",
      "grass",
      "ice",
      "ghost",
      "ground",
      "flying",
      "normal",
    ];

    return (
      <div className="flex flex-col">
        <h1> Pokeomon types</h1>
        <div className="flex flex-col">
          {type.map((types) => (
            <Link key={types} href={`/pokemon/${types}`}>
              {types}
            </Link>
          ))}
        </div>
      </div>
    );
  }

  //if sluge lenght is one
  if (slug?.length === 1) {
    const type = slug[0];

    const res = await fetch(`https://pokeapi.co/api/v2/type/${type}`);

    const data = await res.json();

    return (
      <div className="flex flex-col justify-center items-center">
        <div className="flex flex-wrap gap-4">
          <h1> pokemon {type.toUpperCase()}</h1>
          {data.pokemon.map((p: any) => (
            <Link
              key={p.pokemon.name}
              href={`/pokemon/${type}/${p.pokemon.name}`}
            >
              {p.pokemon.name}
            </Link>
          ))}
        </div>
      </div>
    );
  }

  //if sluge is 2
  if (slug.length >= 2) {
    const type = slug[0];
    const name = slug[1];

    const res = await fetch(`https://pokeapi.co/api/v2/pokemon/${name}`);
    const data = await res.json();
    return (
      <div className="flex justify-center items-center">
        <div className="flex flex-wrap">
          <h1>{data.name.toUpperCase()}</h1>
          <img src={data.sprites.front_default} alt={data.name} />

          <p> Types:{data.types.map((t: any) => t.type.name).join("")}</p>
          <p> Height: {data.height}</p>
          <p> Weigth: {data.weight}</p>
          <h3> stats:</h3>
          <ul>
            {data.stats.map((s: any) => (
              <li key={s.stat.name}>{s.stat.name.toUpperCase()}</li>
            ))}
          </ul>
        </div>
      </div>
    );
  }
}
